// T19 (v2, after the Director's review): shared pieces for the read-only measurements. Nothing here changes the game.
// Fixtures are committed (docs/team/tasks/T19/fixtures/): `strong-step8.json` is the bot's campaign hero for class:seed at Act III step 8
// (tools/sim.mjs campaign(cls, 9000 + 7 s, 2.7), 9 seeds per class, null where the bot campaign did not finish), `mid-act2.json` the end of Act II
// (campaign(cls, 5000 + 11 s, 2), 6 per class). The fixtures were generated by the engine at the revision recorded in each output header.
process.env.RELEASE = '1';
import fs from 'node:fs'; import { execSync } from 'node:child_process';
export const E = await import('../js/engine.js'); export const D = await import('../js/data.js'); export const SIM = await import('./sim.mjs');
export const { smartActs, botShape } = SIM;
export const FIX = new URL('../docs/team/tasks/T19/fixtures/', import.meta.url).pathname;
export const CLASSES = Object.keys(D.CLASSES);
export const revision = () => { try { return execSync('git rev-parse HEAD', { cwd: new URL('..', import.meta.url).pathname }).toString().trim(); } catch { return 'unknown'; } };
const strongAll = JSON.parse(fs.readFileSync(`${FIX}strong-step8.json`, 'utf8')); const midAll = JSON.parse(fs.readFileSync(`${FIX}mid-act2.json`, 'utf8'));
export const strongKeys = Object.keys(strongAll).filter((k) => strongAll[k]); // 'class:seed', in fixture order
export const strongOf = (key) => structuredClone(strongAll[key]);
export const strongByClass = Object.fromEntries(CLASSES.map((c) => [c, strongKeys.filter((k) => k.startsWith(`${c}:`))]));
export const midOf = (cls, i) => { const l = midAll[cls]; return { key: `mid:${cls}:${i % l.length}`, hero: structuredClone(l[i % l.length]) }; };
export const freshOf = (cls, i) => ({ key: `fresh:${cls}:${i % 6}`, hero: E.newHero({ name: `${cls}-new`, cls, seed: 700 + (i % 6) }) });
// ------------------------------------------------------------------------------------------------ statistics
export const mean = (a) => a.reduce((x, y) => x + y, 0) / (a.length || 1);
export const pct = (a, p) => { const s = [...a].sort((x, y) => x - y); return s.length ? s[Math.min(s.length - 1, Math.floor(p * s.length))] : 0; };
export const f0 = (x) => String(Math.round(x)); export const f1 = (x) => (Math.round(x * 10) / 10).toFixed(1);
// Wilson 95% interval for k wins of n fights. It treats fights as independent, which they are not when one hero fixture is fought several times:
// the tables also say how many distinct hero fixtures stand behind each cell.
export function wilson(k, n) { if (!n) return [0, 0]; const z = 1.96; const p = k / n; const d = 1 + z * z / n; const c = (p + z * z / (2 * n)) / d; const h = (z * Math.sqrt(p * (1 - p) / n + z * z / (4 * n * n))) / d; return [Math.max(0, c - h), Math.min(1, c + h)]; }
export const winText = (k, n) => { const [a, b] = wilson(k, n); return `${k}/${n} (${f0(100 * k / Math.max(1, n))}%, ${f0(100 * a)}-${f0(100 * b)}%)`; };
// ------------------------------------------------------------------------------------------------ the encounters
// 'designed': the step 10 boss as the road builds it. 'return': the nemesis return as Dave met it (Vharaxis fled the step 5 elite at 30% health,
// returns at step 8 beside the Call-for-Help pair). Both are RECONSTRUCTIONS: the report lacks the first rounds and the save, so the flight, the wound
// fraction and the 651 starting health are assumptions, not recorded history (1,002 is the captured MAXIMUM health).
export function setCampaign(h, enc) {
  const c = h.campaign; c.nextEnemies = null; c.nextPlace = null; c.nemeses = [];
  if (enc === 'designed') c.step = 10;
  else { c.step = 8; c.nemeses = [{ id: 'vharaxis', name: D.MONSTERS.vharaxis.name, scar: 'blade', wound: 0.3, act: 3, step: 5, grudge: 0, bounty: 1.5 }]; c.nextPlace = 'Wyrmwatch'; c.nextEnemies = ['gloomstalker', 'dirgesinger']; }
  return h;
}
// The corrected returning boss (a proposal under test, nothing applied): the act/step ELITE health basis for the boss, keeping the wound fraction
// (hp/max) and everything else; in a party the party's own health factor still applies on top, exactly as it does to any enemy.
export const eliteBasis = (step = 8) => Math.round(D.MONSTERS.vharaxis.hp * (1 + D.STEP_HP * (step - 1)) * D.SET_PIECE.elite.hp[2]); // Act III
// ARMS of the nemesis comparison. 'unchanged' touches nothing. 'A' corrects the boss health, keeps both foes (and any party goblins). 'B' corrects the boss
// and keeps at most ONE finite companion in the whole starting encounter (the Gloom Stalker; the Dirge Singer and every automatically added party goblin
// are removed). 'C' corrects the boss and removes every other foe (Gloom Stalker, Dirge Singer, party goblins).
export const ARMS = { unchanged: 'as the road builds it', A: 'boss health corrected, both foes and any party goblins kept', B: 'boss health corrected, one finite companion (Gloom Stalker) only; Dirge Singer and party goblins removed', C: 'boss health corrected, boss alone; Gloom Stalker, Dirge Singer and party goblins removed' };
export function applyArm(b, arm) {
  if (!arm || arm === 'unchanged') return;
  const boss = b.enemies.find((e) => e.id === 'vharaxis' || e.tier === 'boss'); if (!boss) return;
  const frac = boss.hp / boss.maxHp; const factor = b.team?.hp || 1; // the party factor, 1 solo
  boss.maxHp = Math.round(eliteBasis(8) * factor); boss.hp = Math.round(boss.maxHp * frac);
  if (arm === 'B') { let kept = 0; b.enemies = b.enemies.filter((e) => e === boss || (e.id === 'gloomstalker' && !kept++)); }
  if (arm === 'C') b.enemies = b.enemies.filter((e) => e === boss);
}
// ------------------------------------------------------------------------------------------------ one hero alone (newBattle / resolve): the genuine solo reference
export const attacking = (e) => !!e?.intent && E.isDamageIntent(e.intent); // the engine's own test (v1 counted any move with f > 0, so a Wing Wall guard counted as an attack)
export function soloFight(hero, enc, arm, seed) {
  const h = setCampaign(structuredClone(hero), enc); const q = E.questsFor(h)[0]; const rng = E.makeRng(seed);
  const b = E.newBattle(h, q, rng, 1); applyArm(b, arm);
  const rows = []; const maxHp = b.maxHp; const start = { enemies: b.enemies.map((e) => ({ id: e.id, hp: e.hp, maxHp: e.maxHp })), maxHp };
  let guard = 0;
  while (!b.outcome && guard++ < 80) {
    const alive = b.enemies.filter((e) => e.hp > 0); const boss = alive.find((e) => e.tier === 'boss');
    E.startRoll(b); botShape(b, rng); const acts = smartActs(b); const heals = b.healsRound || 0; const hp0 = b.hp;
    const mv = boss?.intent ? { v: boss.intent.v, n: boss.intent.n } : null;
    E.resolve(b, acts); const r = b.report;
    rows.push({ hp0, hp1: Math.max(0, b.hp), taken: r.taken, absorbed: r.absorbed, healed: r.healed, heals, alive: alive.length, bossOnly: !!boss && alive.length === 1, boss: !!boss, bossAttacks: boss ? attacking(boss) : false, move: mv, bossHp: boss ? boss.hp : 0, bossMax: boss ? boss.maxHp : 0, blows: (r.acts || []).filter((x) => x.mag > 0).map((x) => ({ v: x.v, mag: x.mag, net: x.net ?? null })) });
  }
  return { outcome: b.outcome || 'timeout', maxHp, start, rows };
}
// ------------------------------------------------------------------------------------------------ a table of heroes (newPartyBattle / resolveParty)
export function tableFight(heroes, enc, arm, seed) {
  const hs = heroes.map((h) => setCampaign(structuredClone(h), enc)); const q = E.questsFor(hs[0])[0]; const rng = E.makeRng(seed);
  const b = E.newPartyBattle(hs, q, rng); b._real = true; applyArm(b, arm);
  const start = { enemies: b.enemies.map((e) => ({ id: e.id, hp: e.hp, maxHp: e.maxHp })), team: b.team };
  const out = { start, boss: b.enemies.find((e) => e.tier === 'boss')?.maxHp || 0, bossOnly: 0, rounds: 0, hits: [], perRound: [] };
  const names = b.fighters.map((f) => f.hero.name); const maxHp = Object.fromEntries(b.fighters.map((f) => [f.hero.name, f.maxHp]));
  let guard = 0;
  while (!b.outcome && guard++ < 80) {
    const alive = b.enemies.filter((e) => e.hp > 0); if (alive.length === 1 && alive[0].tier === 'boss') out.bossOnly++;
    for (let i = 0; i < b.fighters.length; i++) { if (!E.startFighter(b, i)) continue; botShape(b, rng); const o = smartActs(b); E.commitFighter(b); const f = b.fighters[i]; f.target = o.target; f.straight = o.straight; f.locked = true; }
    E.resolveParty(b); out.rounds = b.round; const rep = b.report || {};
    const order = (rep.fighters || []).map((x) => x.name); // acts' parts / nets follow this order
    for (const a of rep.acts || []) { if (!(a.mag > 0)) continue; const k = a.v === 'breath' ? 'breath' : ['strike', 'pierce', 'drain', 'pilfer'].includes(a.v) ? 'strike' : null; if (!k || !a.parts) continue;
      out.hits.push({ k, mag: a.mag, perHero: a.parts.map((p, i) => ({ name: order[i], part: p, net: a.nets?.[i] ?? null, ratio: p / (maxHp[order[i]] || 1) })) }); }
    out.perRound.push({ taken: (rep.fighters || []).reduce((s, x) => s + (x.taken || 0), 0), healed: (rep.fighters || []).reduce((s, x) => s + (x.healed || 0), 0) });
    for (const f of b.fighters) { f.locked = false; f._low = Math.min(f._low ?? 1, Math.max(0, f.hp) / f.maxHp); if (f.hp <= 0) f._fell = 1; }
  }
  const F = b.fighters; out.outcome = b.outcome || 'timeout'; out.names = names;
  out.per = F.map((f) => ({ name: f.hero.name, cls: f.hero.cls, maxHp: f.maxHp, taken: f.stats.taken || 0, dealt: f.stats.dealt || 0, healed: f.stats.healed || 0, low: f._low ?? 1, fell: !!f._fell, revives: f.stats.revives || 0, strength: E.heroStrength(f.hero) }));
  out.m = b.team?.m; out.hpFactor = b.team?.hp; out.flat = b.team?.flat;
  return out;
}
